package com.example.game.data

data class StageTheme(
    val wallHex: Int,
    val glowHex: Int,
    val dotHex: Int
)

class LevelData(
    val width: Int,
    val height: Int,
    val theme: StageTheme,
    val walls: Array<IntArray>,
    val items: Array<IntArray>,
    val spikeGroups: Array<IntArray>,
    val gateX: Int,
    val gateY: Int
) {
    fun copy(): LevelData {
        val wCopy = Array(height) { y -> walls[y].clone() }
        val iCopy = Array(height) { y -> items[y].clone() }
        val sCopy = Array(height) { y -> spikeGroups[y].clone() }
        return LevelData(width, height, theme, wCopy, iCopy, sCopy, gateX, gateY)
    }
}

