    fun loadLevel(n: Int): LevelData? {
        if (n !in LV_ROWS.indices) return null
        val rows = LV_ROWS[n].split("|")
        val h = rows.size
        val w = rows[0].length
        val walls = Array(h) { IntArray(w) }
        val items = Array(h) { IntArray(w) }
        val spikeGroups = Array(h) { IntArray(w) { -1 } }
        var gx = 0
        var gy = 0

        for (y in 0 until h) {
            val rowStr = rows[h - 1 - y]
            for (x in 0 until w) {
                val ch = rowStr[x]
                walls[y][x] = if (ch == '#') 1 else 0
                items[y][x] = when (ch) {
                    '.' -> 1
                    'o' -> 2
                    '^' -> 3
                    '*' -> 4
                    'E' -> 5
                    else -> 0
                }
                if (ch == 'S') {
                    gx = x
                    gy = y
                }
            }
        }

        var gid = 0
        val queue = ArrayDeque<Pair<Int, Int>>()
        for (y in 0 until h) {
            for (x in 0 until w) {
                if (items[y][x] != 3 || spikeGroups[y][x] != -1) continue
                spikeGroups[y][x] = gid
                queue.addLast(x to y)
                while (queue.isNotEmpty()) {
                    val (ax, ay) = queue.removeLast()
                    for (d in DXY) {
                        val nx = ax + d[0]
                        val ny = ay + d[1]
                        if (nx in 0 until w && ny in 0 until h && items[ny][nx] == 3 && spikeGroups[ny][nx] == -1) {
                            spikeGroups[ny][nx] = gid
                            queue.addLast(nx to ny)
                        }
                    }
                }
                gid++
            }
        }

        return LevelData(
            width = w,
            height = h,
            theme = THEMES[n % 10],
            walls = walls,
            items = items,
            spikeGroups = spikeGroups,
            gateX = gx,
            gateY = gy
        )
    }
}
